        """GET an authenticated JSON resource, repeating until a valid answer arrives.

        Returns (data, raw_body_bytes); (None, body) for a 404 when not_found_ok.
        """
        failures = 0
        rate_limits = 0
        while True:
            if self.token is None:
                self.new_token()
            status, headers, body = self._raw("GET", path, self.token)
            self.stats["requests"] += 1
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    data, problem = None, "body is not JSON"
                else:
                    problem = validate(data)
                if problem is None:
                    self.auth_failures_in_a_row = 0
                    return data, body
                self.log(f"GET {path}: 200 but {problem}: {body[:200]!r}")
                self.stats["bad_200"] += 1
