                wait = self._retry_after(headers, body)
                self.log(f"GET {path}: 429 -> waiting {wait}s as instructed; body={body[:120]!r}")
                if rate_limits > MAX_RATE_LIMITS:
                    raise RuntimeError(f"{path}: rate limited too often")
