        if not isinstance(d, dict):
            return "not an object"
        for key in ("page", "total_pages", "items", "next"):
            if key not in d:
                return f"missing key {key!r}"
        if d["page"] != want:
            return f"page field {d['page']!r} != requested {want}"
        if not isinstance(d["items"], list):
            return "items is not a list"
        return None
    return validate


def check_customer(want_id):
    def validate(d):
        if not isinstance(d, dict):
            return "not an object"
        for key in ("id", "name", "region", "tier", "discount_pct"):
            if key not in d:
                return f"missing key {key!r}"
        if d["id"] != want_id:
            return f"id field {d['id']!r} != requested {want_id!r}"
        return None
    return validate


