    if not isinstance(ts, str):
        raise ValueError(f"timestamp is not a string: {ts!r}")
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError(f"timestamp has no offset: {ts!r}")
    return dt.astimezone(timezone.utc)


def dedupe(pages):
    """Return (orders_by_id in first-seen order, listings_seen, conflicting_repeats)."""
    by_id = {}
    listings = 0
    conflicts = []
    for page in pages:
        for item in page["items"]:
            listings += 1
            oid = item["id"]
            if oid in by_id:
                if by_id[oid] != item:
                    conflicts.append((by_id[oid], item))
            else:
                by_id[oid] = item
    return by_id, listings, conflicts


def qualifies(order):
    return order["status"] == "shipped" and RANGE_START <= parse_utc(order["placed_at"]) < RANGE_END


def discounted_cents(amount_cents, discount_pct):
    """amount * (100 - pct) / 100, rounded half up, in exact integer arithmetic."""
    return (amount_cents * (100 - discount_pct) + 50) // 100


# --------------------------------------------------------------------------- commands
def cmd_pages(data_dir):
    pdir = os.path.join(data_dir, "pages")
    os.makedirs(pdir, exist_ok=True)
    api = Api(os.path.join(data_dir, "events.log"))
    visited = []
    totals_seen = set()
    n = 1
    while n is not None:
        data, raw = api.get_json(page_path(n), check_page(n))
        with open(os.path.join(pdir, f"page-{n:03d}.json"), "wb") as fh:
            fh.write(raw)
        visited.append(n)
        totals_seen.add(data["total_pages"])
        api.log(f"page {n}/{data['total_pages']}: {len(data['items'])} items, next={data['next']!r}")
        nxt = data["next"]
        if nxt is None:
            break
        m = re.fullmatch(r"/orders\?page=(\d+)", nxt)
        if not m:
            raise RuntimeError(f"unexpected next link {nxt!r}")
        n2 = int(m.group(1))
        if n2 in visited:
            raise RuntimeError(f"next link loops back to page {n2}")
        if n2 != n + 1:
            api.log(f"NOTE: next link from page {n} points to page {n2}, not {n + 1}")
        n = n2
    api.log(f"pages fetched: {len(visited)} {visited[0]}..{visited[-1]}; total_pages values seen: {sorted(totals_seen)}")
    # reconcile with the advertised page count (fetch any page 'next' skipped over)
    for want in range(1, max(totals_seen) + 1):
        if want not in visited:
            api.log(f"NOTE: page {want} was not reached via next; fetching it directly")
            data, raw = api.get_json(page_path(want), check_page(want))
            with open(os.path.join(pdir, f"page-{want:03d}.json"), "wb") as fh:
                fh.write(raw)
            visited.append(want)
    api.log(f"DONE pages: {sorted(visited) == list(range(1, max(totals_seen) + 1))=}; stats={dict(api.stats)}")


def cmd_customers(data_dir):
    cdir = os.path.join(data_dir, "customers")
    os.makedirs(cdir, exist_ok=True)
    pages = load_pages(data_dir)
    orders, _, _ = dedupe(pages)
    needed = sorted({o["customer_id"] for o in orders.values() if qualifies(o)})
    api = Api(os.path.join(data_dir, "events.log"))
    api.log(f"customers needed (qualifying orders only): {len(needed)}")
    missing = []
    for cid in needed:
        out = os.path.join(cdir, f"{cid}.json")
        if os.path.exists(out):
            continue                      # already cached
        data = None
        for attempt in range(1, 4):       # a 404 gets a couple of repeats before it is believed
            data, raw = api.get_json(f"/customers/{cid}", check_customer(cid), not_found_ok=True)
            if data is not None:
                break
            api.log(f"customer {cid}: 404 (attempt {attempt}); body={raw[:120]!r}")
            time.sleep(1.0 * attempt)
        if data is None:
            missing.append(cid)
            continue
        with open(out, "wb") as fh:
            fh.write(raw)
    api.log(f"DONE customers: fetched={len(os.listdir(cdir))} missing={missing} stats={dict(api.stats)}")


def cmd_compute(data_dir, out_json):
    pages = load_pages(data_dir)
    orders, listings, conflicts = dedupe(pages)
    duplicates_skipped = listings - len(orders)
    cust = {}
    cdir = os.path.join(data_dir, "customers")
    for name in os.listdir(cdir):
        with open(os.path.join(cdir, name), "rb") as fh:
            rec = json.loads(fh.read())
        cust[rec["id"]] = rec

    by_region = {r: 0 for r in REGIONS}
    count = 0
    for oid, o in orders.items():
        if not qualifies(o):
            continue
        c = cust[o["customer_id"]]                       # KeyError => a customer we failed to fetch
        pct = c["discount_pct"]
        assert isinstance(pct, int) and not isinstance(pct, bool) and 0 <= pct <= 100, (oid, c)
        assert c["region"] in by_region, (oid, c)
        amt = o["amount_cents"]
        assert isinstance(amt, int) and not isinstance(amt, bool) and amt >= 0, (oid, o)
        by_region[c["region"]] += discounted_cents(amt, pct)
        count += 1
    result = {
        "total_cents": sum(by_region.values()),
        "order_count": count,
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }
    print(f"pages={len(pages)} listings={listings} distinct={len(orders)} conflicting_repeats={len(conflicts)}")
    print(json.dumps(result, indent=2))
    with open(out_json, "w") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "pages" and len(sys.argv) == 3:
        cmd_pages(sys.argv[2])
    elif cmd == "customers" and len(sys.argv) == 3:
        cmd_customers(sys.argv[2])
    elif cmd == "compute" and len(sys.argv) == 4:
        cmd_compute(sys.argv[2], sys.argv[3])
    else:
        sys.exit(__doc__)

