import collections
import http.client
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
MIN_GAP = 0.2            # polite minimum spacing between requests (seconds)
MAX_FAILURES = 60        # non-429 failures tolerated for one logical request
MAX_RATE_LIMITS = 500    # 429s tolerated for one logical request
REGIONS = ("north", "south", "east", "west")
RANGE_START = datetime(2025, 3, 1, 0, 0, 0, tzinfo=timezone.utc)   # inclusive
RANGE_END = datetime(2025, 6, 1, 0, 0, 0, tzinfo=timezone.utc)     # exclusive (= end of 31 May)
ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}


# --------------------------------------------------------------------------- client
class Api:
    def __init__(self, log_path):
        self.log_path = log_path
        self.token = None
        self.last_call = 0.0
        self.stats = collections.Counter()
        self.auth_failures_in_a_row = 0

    def log(self, msg):
        line = f"{time.strftime('%H:%M:%S')} {msg}"
        print(line, flush=True)
        with open(self.log_path, "a") as fh:
            fh.write(line + "\n")

    def _raw(self, method, path, token):
        gap = time.monotonic() - self.last_call
        if gap < MIN_GAP:
            time.sleep(MIN_GAP - gap)
        req = urllib.request.Request(BASE + path, method=method)
        if token:
            req.add_header("Authorization", f"Bearer {token}")
        try:
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    return resp.status, resp.headers, resp.read()
            except urllib.error.HTTPError as err:
                return err.code, err.headers, err.read()
        except (OSError, http.client.HTTPException) as err:
            return None, None, repr(err).encode()
        finally:
            self.last_call = time.monotonic()

    @staticmethod
    def _retry_after(headers, body):
        waits = []
        if headers is not None and headers.get("Retry-After") is not None:
            try:
                waits.append(float(headers["Retry-After"]))
            except ValueError:
                pass
        try:
            val = json.loads(body).get("retry_after")
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                waits.append(float(val))
        except (ValueError, AttributeError):
            pass
        return max(waits) if waits else None

    def new_token(self):
        failures = 0
        rate_limits = 0
        while True:
            status, headers, body = self._raw("POST", "/token", None)
            self.stats["token_requests"] += 1
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                    if isinstance(tok, str) and tok:
                        self.token = tok
                        self.log(f"TOKEN issued: {tok}")
                        return
                except (ValueError, KeyError, TypeError):
                    pass
                self.log(f"TOKEN 200 but unusable body: {body[:200]!r}")
            elif status == 429:
                rate_limits += 1
                self.stats["429"] += 1
                wait = self._retry_after(headers, body) or 2.0
                self.log(f"TOKEN 429 -> waiting {wait}s (Retry-After); body={body[:120]!r}")
                if rate_limits > MAX_RATE_LIMITS:
                    raise RuntimeError("token endpoint keeps rate limiting")
                time.sleep(wait + 0.25)
                continue
            else:
                self.log(f"TOKEN status={status} body={body[:200]!r}")
            failures += 1
            if failures > MAX_FAILURES:
                raise RuntimeError("could not obtain a token")
            time.sleep(min(0.5 * failures, 5))

    def get_json(self, path, validate, not_found_ok=False):
        """GET an authenticated JSON resource, repeating until a valid answer arrives.

        Returns (data, raw_body_bytes); (None, body) for a 404 when not_found_ok.
        """
        failures = 0
        rate_limits = 0
        while True:
            if self.token is None:
                self.new_token()
            status, headers, body = self._raw("GET", path, self.token)
            self.stats["requests"] += 1
            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    data, problem = None, "body is not JSON"
                else:
                    problem = validate(data)
                if problem is None:
                    self.auth_failures_in_a_row = 0
                    return data, body
                self.log(f"GET {path}: 200 but {problem}: {body[:200]!r}")
                self.stats["bad_200"] += 1
                self.token = None          # a stale token is the most likely cause; get a fresh one
            elif status == 429:
                rate_limits += 1
                self.stats["429"] += 1
                wait = self._retry_after(headers, body)
                self.log(f"GET {path}: 429 -> waiting {wait}s as instructed; body={body[:120]!r}")
                if rate_limits > MAX_RATE_LIMITS:
                    raise RuntimeError(f"{path}: rate limited too often")
                time.sleep((wait if wait is not None else 2.0) + 0.25)
                continue
            elif status in (401, 403):
                self.stats[str(status)] += 1
                self.auth_failures_in_a_row += 1
                self.log(f"GET {path}: {status} (token {self.token}); body={body[:200]!r} -> new token")
                if self.auth_failures_in_a_row > 5:
                    raise RuntimeError(f"{path}: still unauthorized with fresh tokens")
                self.token = None
                continue
            elif status == 404:
                self.stats["404"] += 1
                if not_found_ok:
                    return None, body
                raise RuntimeError(f"{path}: unexpected 404: {body[:200]!r}")
            elif status is None or status >= 500:
                self.stats["5xx_or_conn"] += 1
                self.log(f"GET {path}: status={status} body={body[:200]!r} -> repeating")
            else:
                raise RuntimeError(f"GET {path}: unexpected status {status}: {body[:300]!r}")
            failures += 1
