    """Return (orders_by_id in first-seen order, listings_seen, conflicting_repeats)."""
    by_id = {}
    listings = 0
    conflicts = []
    for page in pages:
        for item in page["items"]:
            listings += 1
            oid = item["id"]
            if oid in by_id:
